def top_k(lst, k):

    if lst == []:
        return lst

    lower = []
    while lst:
        higher = lst[0]
        for plist in lst:
            if plist < higher:
                higher = plist
        lst.remove(higher)
        lower.append(higher)
    pivot = lower[::-1]
    return pivot[:k]

